tools.example:
board(MyBoard) {
  output("elements.txt", "wt") {
    printf("Grid: %f\n", MyBoard.grid.distance);          // data member returning an object
    MyBoard.elements(TheElement)                           // loop member
      printf("%-8s %-8s\n", TheElement.name, TheElement.value);
    }
  }

board(B) output("arcs.txt", "wt") {
  B.wires(W) {
    if (W.arc) {
       real len = u2mm(W.arc.radius) * (W.arc.angle2 - W.arc.angle1) * PI / 180;
       printf("layer %d centre (%.3f %.3f) r=%.3f mm, %.1f..%.1f deg, length %.3f mm\n",
              W.arc.layer, u2mm(W.arc.xc), u2mm(W.arc.yc), u2mm(W.arc.radius),
              W.arc.angle1, W.arc.angle2, len);
       }
    }
  }

board(B) {
  string s;
  sprintf(s, "Drawing extent: (%.2f %.2f) - (%.2f %.2f) mm, %.2f x %.2f mm",
          u2mm(B.area.x1), u2mm(B.area.y1), u2mm(B.area.x2), u2mm(B.area.y2),
          u2mm(B.area.x2 - B.area.x1), u2mm(B.area.y2 - B.area.y1));
  dlgMessageBox(s);
  }

schematic(SCH) output("attributes.txt", "wt") {
  SCH.attributes(A) printf("global %s = %s\n", A.name, A.value);
  SCH.parts(P) {
    P.attributes(A) printf("%s: %s = %s\n", P.name, A.name, A.value);
    }
  }

if (board) board(B) {
   int ne = 0, ns = 0, nv = 0;
   B.elements(E) ++ne;
   B.signals(S) { ++ns; S.vias(V) ++nv; }
   output(filesetext(B.name, ".stat"), "wt")
     printf("%s\nelements %d, signals %d, vias %d, DRC run: %s\n",
            B.name, ne, ns, nv, B.checked ? "yes" : "no");
   }

schematic(SCH) output("busses.txt", "wt") {
  SCH.sheets(SH) {
    SH.busses(BUS) {
      int n = 0;
      BUS.segments(SEG) ++n;
      printf("sheet %d: bus %s, %d segment(s)\n", SH.number, BUS.name, n);
      }
    }
  }

board(B) output("circles.txt", "wt") {
  B.circles(C)
    printf("layer %d: centre (%.3f %.3f) r=%.3f w=%.3f mm%s\n", C.layer,
           u2mm(C.x), u2mm(C.y), u2mm(C.radius), u2mm(C.width), C.width == 0 ? " (filled)" : "");
  }

board(B) output("classes.txt", "wt") {
  B.classes(CL)
    if (CL.name)
       printf("%d %-10s width %.3f drill %.3f clearance %.3f mm\n", CL.number, CL.name,
              u2mm(CL.width), u2mm(CL.drill), u2mm(CL.clearance));
  B.signals(S) printf("%-12s class %d (%s)\n", S.name, S.class.number, S.class.name);
  }

board(B) output("contacts.csv", "wt") {
  B.elements(E) E.footprint.contacts(C)
    printf("%s;%s;%s;%s;%.3f;%.3f\n", E.name, C.name, C.pad ? "THT" : "SMD",
           C.signal, u2mm(C.x), u2mm(C.y));
  }

board(B) output(filesetext(B.name, ".net"), "wt") {
  B.signals(S) {
    printf("%s:", S.name);
    S.contactrefs(CR) printf(" %s.%s", CR.element.name, CR.contact.name);
    printf("\n");
    }
  }

library(L) output("devices.txt", "wt") {
  L.devicesets(DS) DS.devices(D) {
    string t[];
    int n = strsplit(t, D.technologies, ' ');
    for (int i = 0; i < n; ++i) {
        printf("%s%s [%s] -> %s\n", DS.name, D.name, t[i], D.footprint ? D.footprint.name : "-");
        D.attributes(A, t[i]) printf("   %s = %s\n", A.name, A.value);
        }
    }
  }

library(L) output("devicesets.txt", "wt") {
  L.devicesets(DS) {
    printf("%s  prefix=%s  %s\n", DS.name, DS.prefix, DS.headline);
    DS.gates(G) printf("   gate %s: %s\n", G.name, G.symbol.name);
    }
  }

board(B) output("dimensions.txt", "wt") {
  B.dimensions(D) {
    if (D.dtype == DIMENSION_HORIZONTAL)
       printf("horizontal: %.3f mm\n", u2mm(abs(D.x2 - D.x1)));
    D.texts(T) printf("  shows '%s'\n", T.value);
    }
  }

board(B) output(filesetext(B.name, "_xy.csv"), "wt") {
  printf("Ref;Value;Package;X;Y;Rot;Side;MPN\n");
  B.elements(E) {
    if (E.populate)
       printf("%s;%s;%s;%.3f;%.3f;%.0f;%s;%s\n", E.name, E.value, E.footprint.name,
              u2mm(E.x), u2mm(E.y), E.angle, E.mirror ? "Bottom" : "Top", E.attribute["MPN"]);
    }
  }

board(B) {
  if (!B.checked) { dlgMessageBox("!Run DRC first."); exit(1); }
  output(filesetext(B.name, ".drc.txt"), "wt")
    B.errors(ER)
      if (ER.state == ERROR_STATE_ACTIVE)
         printf("%d\t%s\tlayer %d\t(%.3f %.3f)\n", ER.code, ER.description, ER.layer,
                u2mm(ER.x), u2mm(ER.y));
  }

schematic(SCH) output("frames.txt", "wt") {
  SCH.sheets(SH) SH.frames(F)
    printf("sheet %d: %d x %d fields, %.1f x %.1f mm, left border %s\n", SH.number, F.columns, F.rows,
           u2mm(F.x2 - F.x1), u2mm(F.y2 - F.y1), (F.border & FRAME_BORDER_LEFT) ? "on" : "off");
  }

library(L) output("gates.txt", "wt") {
  L.devicesets(DS) DS.gates(G)
    printf("%s.%s symbol=%s swaplevel=%d%s\n", DS.name, G.name, G.symbol.name, G.swaplevel,
           G.addlevel == GATE_ADDLEVEL_REQUEST ? " (request)" : "");
  }

string UnitName(int u)
{
  switch (u) {
    case GRID_UNIT_MIC:  return "mic";
    case GRID_UNIT_MM:   return "mm";
    case GRID_UNIT_MIL:  return "mil";
    case GRID_UNIT_INCH: return "inch";
    }
  return "?";
}
board(B) {
  string s;
  sprintf(s, "Grid %g %s (display unit %s)", B.grid.distance, UnitName(B.grid.unitdist), UnitName(B.grid.unit));
  dlgMessageBox(s);
  }

board(B) output("holes.txt", "wt") {
  B.holes(H)
    printf("hole (%.3f %.3f) drill %.2f mm, stop %.2f mm\n", u2mm(H.x), u2mm(H.y),
           u2mm(H.drill), u2mm(H.diameter[LAYER_TSTOP]));
  B.elements(E) E.footprint.holes(H)
    printf("%s: hole drill %.2f mm\n", E.name, u2mm(H.drill));
  }

schematic(SCH) output("instances.txt", "wt") {
  SCH.sheets(SH) SH.instances(I)
    printf("%-10s sheet %d field %s%s  (%.2f %.2f)\n", I.name, SH.number, I.column, I.row,
           u2inch(I.x), u2inch(I.y));
  }

schematic(SCH) output("junctions.txt", "wt") {
  SCH.sheets(SH) SH.nets(N) N.segments(SEG) SEG.junctions(J)
    printf("sheet %d net %s: junction (%.2f %.2f) inch\n", SH.number, N.name, u2inch(J.x), u2inch(J.y));
  }

schematic(SCH) output("labels.txt", "wt") {
  SCH.sheets(SH) SH.nets(N) N.segments(SEG) SEG.labels(L)
    printf("sheet %d: '%s'%s at (%.2f %.2f)\n", SH.number, L.text.value, L.xref ? " [xref]" : "",
           u2inch(L.x), u2inch(L.y));
  }

board(B) output("layers.txt", "wt") {
  B.layers(L)
    if (L.used) printf("%3d %-12s %s\n", L.number, L.name, L.visible ? "visible" : "hidden");
  }

schematic(SCH) output("used-libs.txt", "wt") {
  SCH.libraries(L) {
    int n = 0;
    L.devicesets(DS) ++n;
    printf("%-20s %d device sets used\n", L.name, n);
    }
  }

schematic(SCH) output("modules.txt", "wt") {
  SCH.modules(M) {
    printf("module %s (prefix %s)\n", M.name, M.prefix);
    M.ports(P) printf("   port %s\n", P.name);
    M.parts(P) printf("   part %s %s\n", P.name, P.value);
    }
  }

schematic(SCH) output("module-instances.txt", "wt") {
  SCH.sheets(SH) SH.moduleinsts(MI)
    printf("%s -> module %s, sheet %d, variant '%s', offset %d\n",
           MI.name, MI.module.name, MI.sheet, MI.modulevariant, MI.offset);
  }

schematic(SCH) output(filesetext(SCH.name, ".netlist"), "wt") {
  SCH.allnets(N) {                    // includes virtual nets of module instances
    printf("%s:", N.name);
    N.pinrefs(P) printf(" %s-%s", P.part.name, P.pin.name);
    printf("\n");
    }
  }

library(L) output("footprints.txt", "wt") {
  L.footprints(F) {
    int n = 0;
    F.contacts(C) ++n;
    printf("%-20s %3d contacts  %s\n", F.name, n, F.headline);
    }
  }

board(B) output("3d-models.txt", "wt") {
  B.elements(E) {
    if (E.package3d)
       printf("%s: %s (%s, version %d)\n", E.name, E.package3d.name,
              urnbase(E.package3d.urn), urnversion(E.package3d.urn));
    else
       printf("%s: no 3D package\n", E.name);
    }
  }

board(B) output("drills.txt", "wt") {
  B.elements(E) E.footprint.contacts(C) {
    if (C.pad)
       printf("%s.%s drill %.2f  top %.2f  bottom %.2f mm%s\n", E.name, C.name,
              u2mm(C.pad.drill), u2mm(C.pad.diameter[LAYER_TOP]), u2mm(C.pad.diameter[LAYER_BOTTOM]),
              C.pad.shape[LAYER_TOP] == PAD_SHAPE_SQUARE ? " square" : "");
    }
  }

schematic(SCH) output(filesetext(SCH.name, "_bom.csv"), "wt") {
  printf("Part;Value;DeviceSet;Variant;Package;MPN\n");
  SCH.allparts(P) {
    if (P.device.footprint)                     // skip frames, supply symbols
       printf("%s;%s;%s;%s;%s;%s\n", P.name, P.value, P.deviceset.name, P.device.name,
              P.device.footprint.name, P.attribute["MPN"]);
    }
  }

schematic(SCH) output("pin-pad.txt", "wt") {
  SCH.nets(N) N.pinrefs(PR) {
    printf("%-10s %s.%s pads:", N.name, PR.part.name, PR.pin.name);
    PR.pin.contacts(C) printf(" %s", C.name);
    printf("%s\n", PR.pin.direction == PIN_DIRECTION_PWR ? " (pwr)" : "");
    }
  }

schematic(SCH) output("connections.txt", "wt") {
  SCH.sheets(SH) SH.nets(N) N.segments(SEG) SEG.pinrefs(PR)
    printf("sheet %d  %-10s %s/%s.%s\n", SH.number, N.name, PR.part.name, PR.instance.name, PR.pin.name);
  }

board(B) output("pours.txt", "wt") {
  B.signals(S) S.polygons(P) {
    int n = 0;
    P.wires(W) ++n;
    printf("%s layer %d rank %d isolate %.3f mm, %d outline wires%s\n", S.name, P.layer, P.rank,
           u2mm(P.isolate), n, P.pour == POLYGON_POUR_HATCH ? " (hatch)" : "");
    }
  }

schematic(SCH) output("ports.txt", "wt") {
  SCH.modules(M) M.ports(P)
    printf("%s.%s dir=%d %s\n", M.name, P.name, P.direction,
           P.border == MODULE_BORDER_LEFT ? "left" : "other side");
  }

schematic(SCH) output("portrefs.txt", "wt") {
  SCH.sheets(SH) SH.nets(N) N.segments(SEG) SEG.portrefs(PR)
    printf("net %s -> %s.%s\n", N.name, PR.moduleinst.name, PR.port.name);
  }

library(L) output("rects.txt", "wt") {
  L.footprints(F) F.rectangles(R)
    printf("%s: layer %d centre (%.3f %.3f) %.3f x %.3f mm, %.0f deg\n", F.name, R.layer,
           u2mm((R.x1 + R.x2) / 2), u2mm((R.y1 + R.y2) / 2),
           u2mm(R.x2 - R.x1), u2mm(R.y2 - R.y1), R.angle);
  }

if (schematic) schematic(SCH) {
   int np = 0, nn = 0, ns = 0;
   SCH.allparts(P) ++np;
   SCH.allnets(N) ++nn;
   SCH.sheets(SH) ++ns;
   string s;
   sprintf(s, "%s\n%d parts, %d nets, %d sheets, ERC run: %s", SCH.name, np, nn, ns, SCH.checked ? "yes" : "no");
   dlgMessageBox(s);
   }

schematic(SCH) output("segments.txt", "wt") {
  SCH.sheets(SH) SH.nets(N) {
    int seg = 0;
    N.segments(SEG) {
      int w = 0, p = 0;
      SEG.wires(W) ++w;
      SEG.pinrefs(PR) ++p;
      printf("sheet %d %s segment %d: %d wires, %d pins\n", SH.number, N.name, ++seg, w, p);
      }
    }
  }

schematic(SCH) output("sheets.txt", "wt") {
  SCH.sheets(SH) {
    int ni = 0;
    SH.instances(I) ++ni;
    printf("sheet %d: %s (%d gates)\n", SH.number, SH.headline, ni);
    }
  }

board(B) output(filesetext(B.name, ".routing.txt"), "wt") {
  B.signals(S) {
    real len = 0;
    int airwires = 0, vias = 0;
    S.wires(W) {
      if (W.layer == LAYER_UNROUTED) ++airwires;
      else {
         real dx = u2mm(W.x2 - W.x1), dy = u2mm(W.y2 - W.y1);
         len += sqrt(dx * dx + dy * dy);
         }
      }
    S.vias(V) ++vias;
    printf("%-12s %8.2f mm  %d vias  %d airwires\n", S.name, len, vias, airwires);
    }
  }

board(B) output("smd-pads.txt", "wt") {
  B.elements(E) E.footprint.contacts(C) {
    if (C.smd)
       printf("%s.%s layer %d  %.3f x %.3f mm  cream %.3f x %.3f\n", E.name, C.name, C.smd.layer,
              u2mm(C.smd.dx), u2mm(C.smd.dy),
              u2mm(C.smd.dx[C.smd.layer == LAYER_TOP ? LAYER_TCREAM : LAYER_BCREAM]),
              u2mm(C.smd.dy[C.smd.layer == LAYER_TOP ? LAYER_TCREAM : LAYER_BCREAM]));
    }
  }

library(L) output("symbols.txt", "wt") {
  L.symbols(S) {
    int n = 0;
    S.pins(P) ++n;
    printf("%-20s %d pins\n", S.name, n);
    }
  }

board(B) output("silk-texts.txt", "wt") {
  B.texts(T)
    if (T.layer == LAYER_TPLACE)
       printf("'%s' at (%.2f %.2f) size %.2f mm%s\n", T.value, u2mm(T.x), u2mm(T.y), u2mm(T.size),
              T.font == FONT_VECTOR ? "" : " (not vector font)");
  B.elements(E) E.texts(T)                  // smashed name/value texts
    printf("%s: '%s' layer %d\n", E.name, T.value, T.layer);
  }

schematic(SCH) {
  string Names[];
  int n = 0;
  SCH.variantdefs(VD) Names[n++] = VD.name;
  output(filesetext(SCH.name, "_variants.txt"), "wt")
    for (int i = 0; i < n; ++i) {
        setvariant(Names[i]);
        printf("[%s]\n", Names[i]);
        SCH.parts(P) if (!P.populate) printf("  %s not populated\n", P.name);
        }
  }

schematic(SCH) output("variant-diff.txt", "wt") {
  printf("Part\tVariant\tValue\tTechn.\tPopulated\n");
  SCH.parts(P) P.variants(V)
    printf("%s\t%s\t%s\t%s\t%s\n", P.name, V.variantdef.name, V.value, V.technology,
           V.populate ? "yes" : "no");
  }

board(B) output("vias.csv", "wt") {
  printf("Signal;X;Y;Drill;Diameter;Layers\n");
  B.signals(S) S.vias(V)
    printf("%s;%.3f;%.3f;%.3f;%.3f;%d-%d\n", S.name, u2mm(V.x), u2mm(V.y), u2mm(V.drill),
           u2mm(V.diameter[LAYER_TOP]), V.start, V.end);
  }

board(B) output("outline.txt", "wt") {
  B.wires(W) {
    if (W.layer == LAYER_DIMENSION) {
       if (W.arc)
          printf("arc  (%.3f %.3f) r=%.3f %.1f..%.1f deg\n", u2mm(W.arc.xc), u2mm(W.arc.yc),
                 u2mm(W.arc.radius), W.arc.angle1, W.arc.angle2);
       else
          printf("line (%.3f %.3f) - (%.3f %.3f)\n", u2mm(W.x1), u2mm(W.y1), u2mm(W.x2), u2mm(W.y2));
       }
    }
  }
